args.command:
cd /tmp/recon-ct
run() { env -i PATH=/usr/bin:/bin HOME=/tmp/fakehome TERM=xterm /workspace/executable "$@"; }
echo '== strip always + color + autodetect plain =='; run --color=always --style=plain --paging=never --strip-ansi=always ansi.txt | od -c

cd /tmp/recon-ct
run() { env -i PATH=/usr/bin:/bin HOME=/tmp/fakehome TERM=xterm /workspace/executable "$@"; }
for h in ':2' '19:' '3:+2' '-2:'; do echo "== -H '$h' (lines 18-20 area, width 6) =="; run --color=always --style=plain --paging=never --terminal-width 6 -H "$h" nums.txt | grep -c $'\e\[48;5;236m'; done
run --decorations=always --paging=never --terminal-width 20 -r 2:3 -r 5:6 nums.txt | python3 -c "
import sys
for line in sys.stdin:
    if '8<' in line: print(repr(line))
"
: | run --decorations=always --paging=never | python3 -c "
import sys
for line in sys.stdin:
    if 'STDIN' in line: print(repr(line))
"
run --decorations=always --paging=never nul.bin | python3 -c "
import sys
for line in sys.stdin:
    if 'BINARY' in line: print(repr(line))
"
run --decorations=always --paging=never empty.txt | python3 -c "
import sys
for line in sys.stdin:
    if 'EMPTY' in line: print(repr(line))
"
